-- 표시를 받는다

@Target({ElementType.METHOD})
@Retention(RetentionPolicy.RUNTIME)
public @interface Traced { String value() default ""; int slowMs() default 500; }

@Around("@annotation(traced)")
public Object t(ProceedingJoinPoint jp, Traced traced) throws Throwable {
    long t0 = System.currentTimeMillis();
    try { return jp.proceed(); }
    finally {
        long ms = System.currentTimeMillis() - t0;
        if (ms > traced.slowMs()) log.warn("느림 {} {}ms (한계 {}ms)",
            traced.value(), ms, traced.slowMs());
    }
}

@Traced(value = "주문 넣기", slowMs = 200)
public void orderItem(String itemId) { ... }

